/// <summary>
/// PricingAttribute of table <c>CustTable</c> field StatisticsGroup.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableStatisticsGroup extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, StatisticsGroup);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    CustTable   custTable;

    while select StatisticsGroup from custTable
        group by StatisticsGroup
    {
        ret.add(custTable.StatisticsGroup);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, StatisticsGroup));
    qbr.value(queryValue(_value));
}
